sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var allocatedBudgetVal = parseFloat(g_form.getValue('allocated_budget').split(';')[1].replace(',',''));
   var consumedBudgetVal = parseFloat(newValue.split(';')[1].replace(',',''));

   if(consumedBudgetVal < 0){
	g_form.showFieldMsg('consumed_budget', 'Consumed Budget Cannot Be Negative', 'error');
   }
   else if(allocatedBudgetVal < consumedBudgetVal){
	g_form.showFieldMsg('consumed_budget', 'Consumed Budget Cannot Be Greater Than Allocated Budget', 'error');
   }
   else{
	g_form.hideFieldMsg('consumed_budget');
   }


}
